"""Small independent bilingual candidates, not new accepted theory or a full corpus."""
import json,pathlib,hashlib
D=pathlib.Path(__file__).parent
J=lambda p:json.loads((D/p).read_text(encoding='utf-8'))
refs=J('INDEX-REFERENCES.json');rows=[]
def add(topic,key,zh,en,selector):
 for lang,text in [('zh-Hans',zh),('en',en)]:
  rows.append(dict(id=f'HD-R69-{topic}-{key}-{lang}',topic=topic,key=key,language=lang,text=text,sha256=hashlib.sha256(text.encode()).hexdigest(),selector=selector,authorship='Independent original short review candidate; not copied source prose',editorial='OWNER_REVIEW_REQUIRED',rights='NOT_CLEARED_FOR_COMMERCIAL_PUBLICATION',publicationAllowed=False,depth='FOUNDATIONAL_PARAGRAPH_NOT_COMPLETE_SECTION',sourceRefs=refs.get({'TYPE':'types','AUTHORITY':'authorities','PROFILE':'profiles','DEFINITION':'definitions','CHANNEL':'channels','CENTER':'centers'}.get(topic,''),{}).get(key.split('-',1)[0] if topic=='CENTER' else key,{}).get('sourceRefs',[])))
types={
'GENERATOR':('生产者的阅读重点是回应已经出现的具体事情，而不是仅凭头脑替自己制造承诺。可以先接触实际任务，再观察回应与持续投入的质量。回应不等于必须接受每个请求；是否承诺仍要结合你的权威、现实资源与拒绝的空间。','For a Generator, the practical emphasis is responding to something concrete rather than creating a commitment solely to satisfy an idea of what should happen. Encounter the actual task and observe the response and the quality of sustained participation. Responding does not require accepting every request; Authority, available resources and room to decline still matter.'),
'MANIFESTING_GENERATOR':('显生生产者仍然需要回应，速度与多线行动不能替代确认。先试一个可逆步骤，检查是否遗漏了重要环节，再告知受影响的人。改变方向可以是调整，不必为了证明效率而把最初的承诺坚持到底。','A Manifesting Generator still begins with response; speed and parallel activity do not replace checking the commitment. Try a reversible step, check for skipped essentials and inform the people affected. A change of direction can be an adjustment rather than a failure, especially when the original task differs from what was expected.'),
'MANIFESTOR':('显示者可以把注意力放在自己准备发起什么，以及这会影响谁。事先告知有助于减少不必要的阻力，但不等于把每个行动交给别人批准。行动仍需考虑你的内在权威、边界、共同责任和现实后果。','A Manifestor can examine what they are ready to initiate and who will be affected. Informing can reduce avoidable resistance without turning every action into a request for permission. Initiative still needs the chart’s Authority process, boundaries, shared responsibilities and attention to real consequences.'),
'PROJECTOR':('投射者可先辨认自己的观察是否被需要，以及对方是否愿意接受。受到认可或邀请不代表必须答应；还须看角色是否清楚、投入是否可持续。日常表达不需要等待一个神秘信号，这里的重点是重大参与关系中的相互认知。','A Projector can examine whether their perspective is wanted and whether another person is willing to receive it. Recognition or an invitation does not oblige acceptance: the role and the sustainability of participation still need checking. Ordinary communication need not wait for a mysterious signal; the emphasis is mutual recognition in significant commitments.'),
'REFLECTOR':('反映者的无定义结构不等于没有性格、能力或方向。可以比较自己在不同场合和时间中的体验，辨认环境与参与对象带来的变化。重大选择宜给观察留下空间，同时遵守现实期限，并把可靠资料与自己的过程一起考虑。','A Reflector’s lack of defined Centers does not mean an absence of character, ability or direction. Compare experiences across settings and time to notice the contribution of surroundings and participants. Leave room for observation in major choices while respecting actual deadlines and considering reliable information alongside that process.')}
for k,(z,e) in types.items():add('TYPE',k,z,e,{'path':'type','equals':k})
authorities={
'EMOTIONAL':('情绪权威的重点是让不同情绪阶段都有机会被看见，而不是要求当下立即确定。可以记录同一选择在不同状态下仍然成立的部分。没有统一的等待时数；紧急安全问题不应为了等待情绪清晰而延误。','Emotional Authority invites noticing a choice across changing emotional states rather than requiring immediate certainty. Record which aspects remain convincing when the state changes. There is no universal waiting period; urgent safety needs should not be delayed in pursuit of emotional clarity.'),
'SACRAL':('荐骨权威可从面对具体选项时的即时回应开始观察，而不是用抽象问题反复逼自己决定。把问题说得清楚、可实际体验，会更容易辨认回应。它仍不是风险评估、事实查证或专业意见的替代品。','Sacral Authority can be explored through the immediate response to concrete options rather than repeated pressure to answer an abstract question. Clear choices that can actually be encountered are easier to examine. This process does not replace risk assessment, fact checking or appropriate professional advice.'),
'SPLENIC':('直觉权威的阅读关注当下短暂而具体的觉察，不把反复担忧自动当作直觉。可以回顾当时注意到了什么，以及随后有哪些可核实资料。不能凭这一分类诊断危险、判断别人是否可信或忽略安全程序。','Splenic Authority concerns brief, situation-specific awareness rather than treating repeated worry as intuition. Review what was actually noticed and what checkable information followed. This classification cannot diagnose danger, establish another person’s trustworthiness or justify ignoring safety procedures.'),
'SELF_PROJECTED':('自我投射权威可以通过听见自己如何谈论方向、身份与选择来探索。可信赖的倾听者帮助你听清自己，并不替你作决定。注意说出的话是否来自自己的方向，而不是为了得到对方认可。','Self-Projected Authority can be explored by hearing how you speak about direction, identity and a choice. A trusted listener helps you hear yourself rather than making the decision for you. Notice whether the words express your own direction or are shaped primarily to secure approval.'),
'EGO_MANIFESTED':('意志显示权威可关注自己真正愿意投入什么，以及能够承担怎样的承诺。表达意愿之前，检查资源、时间与责任边界。愿意不代表永远有力量，也不构成必须向别人证明价值的义务。','Ego-Manifested Authority invites attention to what you genuinely want to undertake and what commitment you can sustain. Check resources, time and responsibilities before announcing it. Willingness is not limitless capacity and does not create an obligation to prove your worth.'),
'EGO_PROJECTED':('意志投射权威需要在被认可的参与关系中，听清自己愿不愿意承担该角色。邀请与意愿缺一不可；不能只因被需要便答应。把承诺的内容、时间和回报说清楚，避免把意志当成无限资源。','Ego-Projected Authority concerns willingness within a relationship that recognizes the contribution being invited. Invitation and willingness both matter; being needed alone does not require acceptance. Clarify the work, time and exchange rather than treating willpower as an unlimited resource.'),
'MENTAL_ENVIRONMENTAL':('环境型权威的探索包含所处空间、交谈对象和自己说出问题时的变化。可以在合适的环境中，与不会替你作决定的人讨论。讨论的作用是听清自己的过程，而不是把多数意见当作最终答案。','Environmental Authority includes the setting, the people present and what becomes clearer as you speak. Discuss the choice in a suitable environment with people who will not decide for you. The purpose is to hear your own process, rather than treating majority opinion as the answer.'),
'LUNAR':('月亮权威可通过一段时间中不同环境与互动的比较来探索，不要求一次体验立即得出终身结论。保留观察记录，有助于区别短暂影响与持续适合的方向。现实期限、医疗与安全需求仍然优先，不把月亮周期当作僵硬的行动禁令。','Lunar Authority can be explored through comparing environments and interactions over time, without expecting one experience to settle a lifelong direction. Notes can help distinguish temporary influences from a more enduring fit. Actual deadlines, medical needs and safety still matter; a lunar cycle is not a rigid prohibition on action.')}
for k,(z,e) in authorities.items():add('AUTHORITY',k,z,e,{'path':'authority','equals':k})
for k,n in [('SINGLE',1),('SPLIT',2),('TRIPLE_SPLIT',3),('NO_DEFINITION',0)]:
 code={'SINGLE':'SINGLE_DEFINITION','SPLIT':'SPLIT_DEFINITION','TRIPLE_SPLIT':'TRIPLE_SPLIT_DEFINITION','NO_DEFINITION':'NO_DEFINITION'}[k]
 z=('本次定义包含'+str(n)+'个由完整通道连接的中心群组。定义描述图上的连通性，不是能力等级，也不代表必须由某个人补全自己。可以观察不同互动是否改变了表达与处理事情的体验，不把这种观察当成对他人的依赖结论。') if n else types['REFLECTOR'][0]
 e=(f'This definition contains {n} connected group'+('s' if n!=1 else '')+' formed by complete Channels. Definition describes connectivity in the chart, not a hierarchy of ability or a need for another person to complete you. Observe how different interactions affect expression and processing without turning the observation into a claim of dependence.') if n else types['REFLECTOR'][1]
 add('DEFINITION',k,z,e,{'path':'definition.definitionCode','equals':code})
lines={1:('调查基础','investigating a foundation'),2:('自然发挥与独处','natural expression and time apart'),3:('试验与修正','trying and revising'),4:('关系中的交流','exchange through relationships'),5:('他人的期待与可行贡献','others’ expectations and practical contribution'),6:('观察、时间与示范','observation, time and example')}
for k in refs['profiles']:
 a,b=map(int,k.split('/'));add('PROFILE',k,f'{k}把{lines[a][0]}与{lines[b][0]}放在一起阅读。两条线的位置不能互换，也不应把某一个角色当成人格的全部。可以回顾一件实际选择，看哪些做法帮助了自己、哪些只是回应别人的期待；这不是个人传记或必然的人生阶段。',f'Profile {k} brings {lines[a][1]} together with {lines[b][1]}. The two positions are not interchangeable and neither role describes the whole person. Review a real choice to distinguish a useful way of participating from an attempt to satisfy expectations; this is not a biography or an inevitable life sequence.',{'path':'profile.profileCode','equals':k})
themes={'43-23':('理解与表达','understanding and expression'),'29-46':('投入与经验','commitment and experience'),'37-40':('支持与互惠','support and reciprocity'),'64-47':('回顾与意义整理','reflection and the organization of meaning'),'18-58':('辨认问题与改善','noticing problems and improvement'),'28-38':('努力与值得投入的方向','effort and a worthwhile direction')}
for key,(z,e) in themes.items():
 canonical=next((k for k,v in refs['channels'].items() if sorted([v['gateA'],v['gateB']])==sorted(map(int,key.split('-')))),key)
 add('CHANNEL',canonical,f'这条完整通道可围绕{z}来观察。先用一个真实情境辨认：相关能力何时有帮助，又何时因时机、角色或承诺不清楚而带来摩擦。完整通道优先于把两个闸门各自的文字相加，但不覆盖类型、权威及现实条件。',f'This complete Channel can be explored through {e}. Use a real situation to examine when that pattern helps and when timing, role or an unclear commitment creates friction. Read the complete Channel before combining isolated Gate descriptions, while retaining the priority of Type, Authority and real conditions.',{'completeChannel':list(map(int,key.split('-')))})
for center in ['HEAD','AJNA','THROAT','G','EGO','SACRAL','SOLAR_PLEXUS','SPLEEN','ROOT']:
 for state in ['DEFINED','UNDEFINED_ACTIVATED','FULLY_OPEN']:
  z={'DEFINED':'该中心由完整通道定义。可以观察这里较持续的运作方式，同时区分自己的习惯与当时的实际需要。定义不是优秀程度，也不保证每一次表达都正确。','UNDEFINED_ACTIVATED':'该中心没有被完整通道定义，但包含实际激活的闸门。不能将它与完全开放中心混为一谈。可以比较不同环境中的体验，记录具体影响，而不是把外来的感受直接当成自己的固定事实。','FULLY_OPEN':'该中心既未定义，也没有本次命盘的闸门激活。完全开放不代表空缺或缺陷。可以从真实互动中学习辨认变化，不根据一张图推定疾病、能力缺失或他人的影响必然发生。'}[state]
  e={'DEFINED':'This Center is defined through a complete Channel. Observe its more consistent operation while distinguishing a familiar habit from what the situation actually needs. Definition is not a rating of excellence or a guarantee that every expression is correct.','UNDEFINED_ACTIVATED':'This Center is not defined by a complete Channel, but it does contain activated Gates. It must not be described as fully open. Compare experiences across settings and record specific influences rather than turning an incoming feeling into a fixed personal fact.','FULLY_OPEN':'This Center is undefined and has no Gate activation in this chart. Fully open does not mean empty or defective. Learn from actual interactions without using the diagram to infer illness, incapacity or an inevitable influence from another person.'}[state]
  add('CENTER',center+'-'+state,z,e,{'center':center,'state':state})
(D/'COMMON-SEMANTIC-CANDIDATES.json').write_text(json.dumps({'modules':rows,'full17SectionCorpus':False,'quadruple':'DEFERRED_NO_TRIPLE_FALLBACK','reuse':'Existing source IDs and typed runtime fields; short candidate paragraphs do not replace accepted chapters'},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print({'commonBilingualCandidates':len(rows),'commercialAdmitted':0})
